//! Metrics of TH Sarabun New and TH SarabunPSK (Thai national fonts from SIPA, version 1.3 2011),
//! for drawing their text with the bundled Sarabun when they are not installed: the advance width
//! of every character they map (font units, 1000 per em), their kerning pairs, and the scale that
//! makes Sarabun's letters as tall as theirs (the height of ก for Thai, of x for Latin).
//!
//! Measured from the fonts themselves (hmtx; kerning by shaping every pair of spacing characters
//! with and without `kern`): TH SarabunPSK has the same widths and kerning as TH Sarabun New in
//! every style. Both: unitsPerEm 1000, hhea 844/-457 with a line gap of 30, usWin 844/457, so Word
//! for Windows sets single-spaced lines 1.331 em apart. Generated; do not edit by hand.

/// One style's measurements.
pub(crate) struct ThSarabunStyle {
    /// Sarabun's glyphs times this are as tall as TH Sarabun's: Thai letters (ก) and Latin (x).
    pub thai_scale: f32,
    pub latin_scale: f32,
    /// (character, advance width) sorted by character.
    pub advances: &'static [(char, u16)],
}

/// Line metrics in font units, the way Word for Windows measures them: (ascent with the external
/// leading, descent).
pub(crate) const LINE: (f64, f64) = (874.0, 457.0);

